function chaineLaPlusLongue(tableau) {
    if (!tableau || tableau.length === 0) return '';
    let maxLen = -1;
    let result = '';
    for (const s of tableau) {
        if (s.length > maxLen) {
            maxLen = s.length;
            result = s;
        }
    }
    return result;
