```javascript
function pgcd(a, b) {
  // Algorithme d'Euclide (a et b > 0)
  while (b !== 0) {
    const temp = b;
    b = a % b;
    a = temp;
  }
  return a;
}
// Exemple : pgcd(12, 8) === 4
```

