function fusionTriee(a, b) {
  const result = [];
  let i = 0;
  let j = 0;
  // Fusion des deux parties encore à traiter
  while (i < a.length && j < b.length) {
    if (a[i] <= b[j]) {
      result.push(a[i]);
      i++;
    } else {
      result.push(b[j]);
      j++;
    }
  }
  // Récupération des éléments restants
  while (i < a.length) { result.push(a[i]); i++; }
  while (j < b.length) { result.push(b[j]); j++; }
  return result;
}
// Exemple : fusionTriee([1, 3, 5], [2, 4, 6]) === [1, 2, 3, 4, 5, 6]
